package dev.dreamwalker.bloodbornedw.link;

import dev.dreamwalker.bloodbornedw.architecture.*;
import dev.dreamwalker.bloodbornerp.object.*;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;
import net.minecraft.test.*;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.util.math.BlockPos;
import net.minecraft.nbt.NbtCompound;
import java.util.*;

/** Technical server semantics only; ordinary mouse/GUI packet proof is separate. */
public final class MechanismRulesGameTests implements FabricGameTest {
    @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,tickLimit=100,batchId="v12_groups")
    public void toolAllGroupRepeatsAreSilentAndAnyMemberClosesAndResets(TestContext c){var p=player(c);RpObjectEntity a=object(c,"lever_1",1),b=object(c,"lever_2",3),door=object(c,"door_1",9);c.assertTrue(MechanismLinks.linkLevers(p,List.of(a.getUuid(),b.getUuid()),door.getUuid()),"two lever tool group saved");
        c.assertTrue(ObjectPolicies.leversOnly(p.getServer(),MechanismLinks.TargetRef.rp(door)),"successful group immediately makes target lever-only");door.interact(p,net.minecraft.util.Hand.MAIN_HAND);c.assertTrue(!door.isOpen()&&!MechanismGroups.active(p.getServer(),a.getUuid())&&!MechanismGroups.active(p.getServer(),b.getUuid()),"ordinary target RMB cannot bypass newly linked ALL");
        c.assertTrue(a.interact(p,net.minecraft.util.Hand.MAIN_HAND).isAccepted()&&!door.isOpen()&&MechanismGroups.active(p.getServer(),a.getUuid()),"first ordinary use latches one source");NbtCompound once=MechanismGroups.get(p.getServer()).writeNbt(new NbtCompound());a.interact(p,net.minecraft.util.Hand.MAIN_HAND);c.assertTrue(once.equals(MechanismGroups.get(p.getServer()).writeNbt(new NbtCompound()))&&!door.isOpen(),"repeat of activated source is a complete no-op");
        b.interact(p,net.minecraft.util.Hand.MAIN_HAND);c.assertTrue(door.isOpen()&&MechanismGroups.active(p.getServer(),a.getUuid())&&MechanismGroups.active(p.getServer(),b.getUuid()),"all sources open real target");a.interact(p,net.minecraft.util.Hand.MAIN_HAND);c.assertTrue(door.isOpen(),"busy authored opening cannot be interrupted");settle(door);a.interact(p,net.minecraft.util.Hand.MAIN_HAND);c.assertTrue(!door.isOpen()&&!MechanismGroups.active(p.getServer(),a.getUuid())&&!MechanismGroups.active(p.getServer(),b.getUuid()),"any member after opening closes and resets all");settle(door);b.interact(p,net.minecraft.util.Hand.MAIN_HAND);c.assertTrue(!door.isOpen()&&MechanismGroups.active(p.getServer(),b.getUuid()),"next cycle again requires every lever");a.interact(p,net.minecraft.util.Hand.MAIN_HAND);c.assertTrue(door.isOpen(),"new complete cycle opens");cleanup(p,a,b,door);c.complete();}
    @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,tickLimit=100,batchId="v12_groups")
    public void sixLeverFlagsPersistAndSeventhOrDuplicatesCannotMutateGroup(TestContext c){var p=player(c);List<RpObjectEntity> levers=new ArrayList<>();for(int i=0;i<7;i++)levers.add(object(c,"lever_1",1+i*2));RpObjectEntity door=object(c,"door_1",20);List<UUID> six=levers.subList(0,6).stream().map(RpObjectEntity::getUuid).toList();c.assertTrue(MechanismLinks.linkLevers(p,six,door.getUuid()),"six sources accepted");for(int i=0;i<3;i++)MechanismLinks.useLinkedLever(levers.get(i),p);NbtCompound before=MechanismGroups.get(p.getServer()).writeNbt(new NbtCompound());c.assertTrue(MechanismGroups.fromNbt(before).writeNbt(new NbtCompound()).equals(before),"partial activation and exact identities roundtrip typed NBT");
        c.assertTrue(!MechanismLinks.linkLevers(p,levers.stream().map(RpObjectEntity::getUuid).toList(),door.getUuid())&&!MechanismLinks.linkLevers(p,List.of(levers.get(0).getUuid(),levers.get(0).getUuid()),door.getUuid())&&before.equals(MechanismGroups.get(p.getServer()).writeNbt(new NbtCompound())),"seventh/duplicate cannot replace valid group");for(int i=3;i<6;i++)MechanismLinks.useLinkedLever(levers.get(i),p);c.assertTrue(door.isOpen(),"all six required persistent flags eventually open");for(var lever:levers)lever.removeObject();door.removeObject();p.discard();c.complete();}
    @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,tickLimit=100,batchId="v12_groups")
    public void singleLeverTogglesAndBrokenMemberOrReplacementDeletesWholeGroup(TestContext c){var p=player(c);RpObjectEntity a=object(c,"lever_1",1),b=object(c,"lever_2",3),door=object(c,"door_1",9),other=object(c,"door_2",15);c.assertTrue(MechanismLinks.linkLevers(p,List.of(a.getUuid()),door.getUuid()),"single source group");MechanismLinks.useLinkedLever(a,p);c.assertTrue(door.isOpen(),"single source opens");settle(door);MechanismLinks.useLinkedLever(a,p);c.assertTrue(!door.isOpen(),"same source closes after clip");settle(door);
        MechanismLinks.useLinkedLever(a,p);settle(door);c.assertTrue(ObjectPolicies.setManual(p,MechanismLinks.TargetRef.rp(door),false)&&door.interact(p,net.minecraft.util.Hand.MAIN_HAND).isAccepted()&&!door.isOpen(),"explicitly restored manual mode may close opened target");settle(door);MechanismLinks.useLinkedLever(a,p);c.assertTrue(door.isOpen(),"manual close cannot leave single-source latch stuck");settle(door);MechanismLinks.useLinkedLever(a,p);settle(door);
        c.assertTrue(MechanismLinks.linkLevers(p,List.of(a.getUuid(),b.getUuid()),door.getUuid())&&MechanismLinks.linkLevers(p,List.of(b.getUuid()),other.getUuid()),"replacement can reuse selected member");c.assertTrue(MechanismLinks.groupMembers(p.getServer(),a.getUuid()).isEmpty()&&MechanismLinks.targets(a).isEmpty()&&MechanismLinks.groupMembers(p.getServer(),b.getUuid()).equals(Set.of(b.getUuid(),other.getUuid())),"replacement removes entire previous group");other.removeObject();c.assertTrue(MechanismLinks.groupMembers(p.getServer(),b.getUuid()).isEmpty()&&!MechanismLinks.useLinkedLever(b,p),"breaking target removes source binding too");cleanup(p,a,b,door);c.complete();}
    @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,tickLimit=100,batchId="v12_groups")
    public void blockedToolCloseKeepsIntentAndFlagsUntilSafeWithoutRepeatReversal(TestContext c){var p=player(c);RpObjectEntity a=object(c,"lever_1",1),door=object(c,"door_1",9);MechanismLinks.linkLevers(p,List.of(a.getUuid()),door.getUuid());MechanismLinks.useLinkedLever(a,p);settle(door);var living=net.minecraft.entity.EntityType.ARMOR_STAND.create(c.getWorld());living.setPosition(door.getPos());c.getWorld().spawnEntity(living);MechanismLinks.useLinkedLever(a,p);var ref=MechanismLinks.TargetRef.rp(door);c.assertTrue(door.isOpen()&&MechanismLinks.pending(p.getServer(),ref)&&MechanismGroups.active(p.getServer(),a.getUuid()),"unsafe close waits with current activation retained");NbtCompound saved=MechanismGroups.get(p.getServer()).writeNbt(new NbtCompound());MechanismLinks.useLinkedLever(a,p);c.assertTrue(saved.equals(MechanismGroups.get(p.getServer()).writeNbt(new NbtCompound())),"repeat cannot reverse pending safe close");living.discard();MechanismLinks.retryPending(p.getServer(),256);c.assertTrue(!door.isOpen()&&!MechanismLinks.pending(p.getServer(),ref)&&!MechanismGroups.active(p.getServer(),a.getUuid()),"safe retry closes then resets exactly once");cleanup(p,a,door);c.complete();}
    @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,tickLimit=100,batchId="v10_rules")
    public void allUsesPersistentFlagsAndClosesOnlyOnConditionTransition(TestContext c){var p=player(c);RpObjectEntity a=object(c,"lever_1",1),b=object(c,"lever_2",3),door=object(c,"door_1",9);var r=MechanismRules.create(p,"ALL durable");add(c,p,r,a,true);add(c,p,r,b,true);add(c,p,r,door,false);c.assertTrue(MechanismRules.configure(p,r.id,r.name,MechanismRules.Condition.ALL,MechanismRules.Effect.TOGGLE),"configure ALL");
        MechanismRules.pulse(a);c.assertTrue(!door.isOpen()&&MechanismRules.flag(p.getServer(),a.getUuid()),"one source is persistent active but1/2 does not open");MechanismRules.pulse(b);c.assertTrue(door.isOpen(),"all2/2 opens actual target");for(int i=0;i<80;i++){a.tick();b.tick();}c.assertTrue(door.isOpen()&&MechanismRules.flag(p.getServer(),a.getUuid()),"temporary lever animation does not clear source flag");settle(door);MechanismRules.pulse(a);c.assertTrue(!door.isOpen(),"ALL false transition closes rather than toggles blindly");cleanup(p,a,b,door);c.complete();}
    @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,tickLimit=100,batchId="v10_rules")
    public void creationOrderSurvivesTypedRoundtripAndLastActualActionWins(TestContext c){var p=player(c);RpObjectEntity a=object(c,"lever_1",1),door=object(c,"door_1",9);MechanismRules.Rule open=MechanismRules.create(p,"first OPEN"),close=MechanismRules.create(p,"last CLOSE");for(var r:List.of(open,close)){add(c,p,r,a,true);add(c,p,r,door,false);}MechanismRules.configure(p,open.id,open.name,MechanismRules.Condition.ANY,MechanismRules.Effect.OPEN);MechanismRules.configure(p,close.id,close.name,MechanismRules.Condition.ANY,MechanismRules.Effect.CLOSE);MechanismRules.pulse(a);var ref=MechanismLinks.TargetRef.rp(door);c.assertTrue(door.isOpen()&&MechanismRules.pending(p.getServer(),ref),"later CLOSE waits rather than truncating the first OPEN clip");NbtCompound n=MechanismRules.get(p.getServer()).writeNbt(new NbtCompound());NbtCompound round=MechanismRules.fromNbt(n).writeNbt(new NbtCompound());c.assertTrue(round.equals(n),"typed flags, order, pending CLOSE and members survive save decode");settle(door);MechanismRules.retry(p.getServer(),256);c.assertTrue(!door.isOpen()&&!MechanismRules.pending(p.getServer(),ref),"creation-ordered final CLOSE applies once after real opening clip finishes");cleanup(p,a,door);c.complete();}
    @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,tickLimit=100,batchId="v10_rules")
    public void breakingRequiredSourceRemovesWholeLegacyComponent(TestContext c){var p=player(c);RpObjectEntity a=object(c,"lever_1",1),b=object(c,"lever_2",3),door=object(c,"door_1",9);var r=MechanismRules.create(p,"required sources");add(c,p,r,a,true);add(c,p,r,b,true);add(c,p,r,door,false);MechanismRules.configure(p,r.id,r.name,MechanismRules.Condition.ALL,MechanismRules.Effect.TOGGLE);MechanismRules.pulse(a);b.removeObject();c.assertTrue(MechanismRules.rule(p.getServer(),r.id)==null&&!door.isOpen()&&MechanismLinks.groupMembers(p.getServer(),a.getUuid()).isEmpty(),"breaking any member removes the whole legacy component");MechanismRules.pulse(a);c.assertTrue(!door.isOpen(),"removed component cannot act on former target");cleanup(p,a,door);c.complete();}
    @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,tickLimit=100,batchId="v10_rules")
    public void resetSharedAllFlagsDoesNotGenerateAnyPulse(TestContext c){var p=player(c);RpObjectEntity a=object(c,"lever_1",1),allDoor=object(c,"door_1",9),anyDoor=object(c,"door_2",14);MechanismRules.Rule all=MechanismRules.create(p,"all"),any=MechanismRules.create(p,"any");add(c,p,all,a,true);add(c,p,all,allDoor,false);add(c,p,any,a,true);add(c,p,any,anyDoor,false);MechanismRules.configure(p,all.id,all.name,MechanismRules.Condition.ALL,MechanismRules.Effect.TOGGLE);MechanismRules.pulse(a);c.assertTrue(allDoor.isOpen()&&anyDoor.isOpen(),"successful event delivers bothconditions");c.assertTrue(MechanismRules.reset(p,all.id),"explicit reset accepted");c.assertTrue(allDoor.isOpen()&&MechanismRules.pending(p.getServer(),MechanismLinks.TargetRef.rp(allDoor))&&!MechanismRules.flag(p.getServer(),a.getUuid()),"reset immediately clears logical flag but preserves current ALL open clip until safe CLOSE");settle(allDoor,anyDoor);MechanismRules.retry(p.getServer(),256);c.assertTrue(!allDoor.isOpen()&&anyDoor.isOpen()&&!MechanismRules.pending(p.getServer(),MechanismLinks.TargetRef.rp(allDoor)),"reset closes only ALL after its clip and never generates an ANY pulse");cleanup(p,a,allDoor,anyDoor);c.complete();}
    @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,tickLimit=100,batchId="v10_rules")
    public void mixedPersistentAndPulseTargetsRunOnceAtAllTrueOnly(TestContext c){var p=player(c);RpObjectEntity a=object(c,"lever_1",1),door=object(c,"door_1",9),gate=object(c,"wood_gate",19);var r=MechanismRules.create(p,"mixed");add(c,p,r,a,true);add(c,p,r,door,false);add(c,p,r,gate,false);c.assertTrue(MechanismRules.configure(p,r.id,r.name,MechanismRules.Condition.ALL,MechanismRules.Effect.TOGGLE),"mixedsupported");MechanismRules.pulse(a);c.assertTrue(door.isOpen()&&gate.woodGatePulseActive()&&!gate.isOpen(),"actual door open andsingle gateclip nofakeOPEN");for(int i=0;i<32;i++)gate.tick();MechanismRules.retry(p.getServer(),256);c.assertTrue(!gate.woodGatePulseActive(),"ticks/retry don't repeat satisfiedALLpulse");MechanismRules.pulse(a);var ref=MechanismLinks.TargetRef.rp(door);c.assertTrue(door.isOpen()&&MechanismRules.pending(p.getServer(),ref)&&!gate.woodGatePulseActive(),"ALLfalse queues one CLOSE during opening without another gate pulse");settle(door);MechanismRules.retry(p.getServer(),256);c.assertTrue(!door.isOpen()&&!MechanismRules.pending(p.getServer(),ref)&&!gate.woodGatePulseActive(),"ALLfalse close applies after real clip without inventing gate OPEN");cleanup(p,a,door,gate);c.complete();}
    @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,tickLimit=100,batchId="v10_rules")
    public void pendingSafeCloseWaitsAndQueueAndInitiatorPersist(TestContext c){var p=player(c);RpObjectEntity a=object(c,"lever_1",1),door=object(c,"door_1",9);door.setOpen(true);settle(door);var r=MechanismRules.create(p,"safeclose");add(c,p,r,a,true);add(c,p,r,door,false);MechanismRules.configure(p,r.id,r.name,MechanismRules.Condition.ANY,MechanismRules.Effect.CLOSE);var living=net.minecraft.entity.EntityType.ARMOR_STAND.create(c.getWorld());living.setPosition(door.getPos());c.getWorld().spawnEntity(living);MechanismLinks.noteInitiator(a,p);MechanismRules.pulse(a);var ref=MechanismLinks.TargetRef.rp(door);c.assertTrue(door.isOpen()&&MechanismRules.pending(p.getServer(),ref),"real occupant keeps actualstateopen queued");NbtCompound n=MechanismRules.get(p.getServer()).writeNbt(new NbtCompound());c.assertTrue(n.getList("Queue",10).stream().map(v->(NbtCompound)v).anyMatch(v->v.getCompound("Target").getUuid("Instance").equals(door.getUuid())&&v.getCompound("Initiator").getUuid("UUID").equals(p.getUuid())),"queued exacttarget and initiator typed persisted");living.discard();MechanismRules.retry(p.getServer(),256);c.assertTrue(!door.isOpen()&&!MechanismRules.pending(p.getServer(),ref),"pendingclose commitsonly when safe");cleanup(p,a,door);c.complete();}
    private static void settle(RpObjectEntity... objects){for(var object:objects){int limit=2;for(String phase:List.of("open","close")){var clip=object.asset().clip(phase);if(clip!=null)limit=Math.max(limit,(int)Math.ceil(clip.seconds()*20)+2);}for(int tick=0;object.animationBusy()&&tick<limit;tick++)object.tick();if(object.animationBusy())throw new AssertionError("Authored target clip did not finish: "+object.assetId());}}
    private static ServerPlayerEntity player(TestContext c){var p=c.createMockCreativeServerPlayerInWorld();p.getAbilities().creativeMode=true;p.getAbilities().allowModifyWorld=true;return p;}
    private static RpObjectEntity object(TestContext c,String asset,int x){var world=c.getWorld();BlockPos root=c.getAbsolutePos(new BlockPos(x,2,1));world.getChunk(root);var rp=ObjectRegistry.TYPES.get(asset).create(world);c.assertTrue(rp!=null,"registered fixture type "+asset);rp.refreshPositionAndAngles(root.getX()+.5,root.getY(),root.getZ()+.5,0,0);c.assertTrue(world.spawnEntity(rp)&&world.getEntity(rp.getUuid())==rp,"real fixture spawn "+asset+" at "+root);return rp;}
    private static void add(TestContext c,ServerPlayerEntity p,MechanismRules.Rule r,RpObjectEntity entity,boolean source){c.assertTrue(MechanismRules.add(p,r.id,MechanismLinks.TargetRef.rp(entity),source),"actual instance accepted:"+entity.assetId());}
    private static void cleanup(ServerPlayerEntity p,RpObjectEntity... entities){for(var e:entities)e.removeObject();p.discard();}
}
